        ok({schema: with.schema, version: with.version, axis: with.axis, vertex_count: with.vertex_count, positions: with.positions, edge_count: with.edge_count, edges: with.edges, edge_ids: with.edge_ids, edge_colors: with.edge_colors, label_count: with.label_count, label_ids: with.label_ids, label_texts: with.label_texts, label_positions: with.label_positions, frame_count: with.frame_count, frames: with.frames, panel_count: n + 1, panel_ids: u:rs_delimited_append(scene.panel_ids, n, id), panel_titles: u:rs_delimited_append(scene.panel_titles, n, title), panel_docs: u:rs_delimited_append(scene.panel_docs, n, doc), panel_bounds: concat(scene.panel_bounds, bounds), panel_colors: concat(scene.panel_colors, color)})
      }
